// ---------- POWER SWITCH ----------
const body = document.body;
const sw = document.getElementById('powerSwitch');
const knob = document.getElementById('knobLabel');
const cta = document.getElementById('switchCta');

function spark(x,y){
  // burst of round sparks (bigger, denser, further-flying)
  for(let i=0;i<42;i++){
    const s = document.createElement('div');
    s.className='spark';
    const size = 4+Math.random()*9;
    s.style.width = size+'px';
    s.style.height = size+'px';
    s.style.left = x+'px';
    s.style.top = y+'px';
    document.body.appendChild(s);
    const ang = Math.random()*Math.PI*2;
    const dist = 90+Math.random()*220;
    s.animate([
      {transform:'translate(-50%,-50%) scale(1.3)',opacity:1},
      {transform:`translate(${Math.cos(ang)*dist-50}%, ${Math.sin(ang)*dist-50}%) scale(.2)`,opacity:0}
    ],{duration:650+Math.random()*500,easing:'cubic-bezier(.2,.8,.3,1)'});
    setTimeout(()=>s.remove(),1200);
  }
  // jagged bolt lines shooting outward
  for(let i=0;i<12;i++){
    const b = document.createElement('div');
    b.className='spark bolt-line';
    const ang = (Math.PI*2/12)*i + (Math.random()*.4-.2);
    const len = 100+Math.random()*130;
    b.style.width='4px';
    b.style.height=len+'px';
    b.style.left = x+'px';
    b.style.top = y+'px';
    b.style.transformOrigin='top center';
    b.style.transform = `translate(-50%,0) rotate(${ang}rad)`;
    document.body.appendChild(b);
    b.animate([
      {opacity:1,transform:`translate(-50%,0) rotate(${ang}rad) scaleY(0)`},
      {opacity:1,transform:`translate(-50%,0) rotate(${ang}rad) scaleY(1)`,offset:.35},
      {opacity:0,transform:`translate(-50%,0) rotate(${ang}rad) scaleY(1.2)`}
    ],{duration:480,easing:'ease-out'});
    setTimeout(()=>b.remove(),520);
  }
  // full-screen flash (screen strobe — always works, no permission needed)
  const flash=document.createElement('div');
  flash.style.cssText='position:fixed;inset:0;background:#fff;opacity:0;pointer-events:none;z-index:55;';
  document.body.appendChild(flash);
  flash.animate([{opacity:.85},{opacity:.15,offset:.5},{opacity:0}],{duration:220,easing:'ease-out'});
  setTimeout(()=>flash.remove(),260);

  // real camera flash (torch) burst for ~0.2s, on devices/browsers that support it.
  // Browser will show its own native camera-permission prompt the first time —
  // that step can't be skipped or done silently, it's a browser security rule.
  fireTorchFlash(200);
}

// Attempts to blip the device's rear camera flash on for `ms` milliseconds.
// Not supported on iOS Safari and many browsers — fails silently there,
// the white screen-strobe above already covers the "shock" effect for everyone.
let _torchTrack = null;
async function fireTorchFlash(ms){
  try{
    if(!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) return;
    const stream = await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'}}});
    const track = stream.getVideoTracks()[0];
    const caps = track.getCapabilities ? track.getCapabilities() : {};
    if(!caps.torch){ track.stop(); return; }
    _torchTrack = track;
    await track.applyConstraints({advanced:[{torch:true}]});
    setTimeout(async ()=>{
      try{ await track.applyConstraints({advanced:[{torch:false}]}); }catch(e){}
      track.stop();
      if(_torchTrack===track) _torchTrack=null;
    }, ms);
  }catch(e){
    // camera unavailable / permission denied / unsupported — ignore, screen flash already fired
  }
}

let powered = false;
const contentEl = document.getElementById('content');

function pressPulse(){
  sw.classList.add('pressed');
  sw.animate([
    {transform:'scale(1)'},
    {transform:'scale(.9)',offset:.3},
    {transform:'scale(1.08)',offset:.6},
    {transform:'scale(1)'}
  ],{duration:380,easing:'cubic-bezier(.34,1.56,.64,1)'});
  setTimeout(()=>sw.classList.remove('pressed'),380);
}

sw.addEventListener('click',(e)=>{
  powered = !powered;
  pressPulse();
  const rect = sw.getBoundingClientRect();
  spark(rect.left+rect.width/2, rect.top+rect.height/2);
  if(powered){
    body.classList.add('powered');
    knob.textContent='ON';
    cta.textContent='PANEL AKTIF';
    contentEl.style.display='block';
    // force reflow so the reveal animation replays every time it's switched on
    void contentEl.offsetWidth;
    contentEl.classList.add('revealed');
    setTimeout(()=>{
      document.getElementById('about').scrollIntoView({behavior:'smooth',block:'start'});
    },500);
  }else{
    body.classList.remove('powered');
    knob.textContent='OFF';
    cta.textContent='TEKAN UNTUK MENYALAKAN';
    contentEl.classList.remove('revealed');
    contentEl.style.display='none';
    window.scrollTo({top:0,behavior:'smooth'});
  }
});

