// ---------- LIGHTBOX ----------
const lb = document.getElementById('lightbox');
const lbImg = document.getElementById('lbImg');
const lbCount = document.getElementById('lbCount');
let lbIndex = 0;
function openLightbox(i){
  lbIndex = i;
  updateLightbox();
  lb.classList.add('open');
}
function updateLightbox(){
  lbImg.src = photos[lbIndex].src;
  lbCount.textContent = (lbIndex+1)+' / '+photos.length;
}
document.getElementById('lbClose').addEventListener('click',()=>lb.classList.remove('open'));
document.getElementById('lbPrev').addEventListener('click',()=>{lbIndex=(lbIndex-1+photos.length)%photos.length;updateLightbox();});
document.getElementById('lbNext').addEventListener('click',()=>{lbIndex=(lbIndex+1)%photos.length;updateLightbox();});
lb.addEventListener('click',(e)=>{if(e.target===lb)lb.classList.remove('open');});